    """Pick one value from list based on criterion"""
    unique = sorted(set(vals))
    if criterion == 'min_freq':
        return min(unique, key=lambda v: (freq.get(v, 0), v))
    elif criterion == 'max_freq':
        return max(unique, key=lambda v: (freq.get(v, 0), v))
    elif criterion == 'min_val':
        return min(unique)
    elif criterion == 'max_val':
        return max(unique)
    else:
        return unique[0]

